import { test, expect } from '@playwright/test';

test.describe('Table Row Filtering by Search Input', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should filter table rows by typing in search input and display matching results', async ({ page }) => {
    // Verify initial table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify initial row count
    const rowCount = page.locator('[data-testid="table-row"]').count();
    expect(rowCount).toBeGreaterThan(0);

    // Verify search input is visible and has placeholder
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();
    await expect(searchInput).toContainText('Search');

    // Verify filter button is visible
    const filterButton = page.getByRole('button', { name: /filter/i });
    await expect(filterButton).toBeVisible();

    // Verify no results are displayed initially
    const resultCount = page.locator('[data-testid="table-result-count"]').textContent().trim();
    expect(resultCount).toBe('0 results');

    // Type a search term
    await searchInput.fill('test');

    // Verify search input has value
    await expect(searchInput).toHaveValue('test');

    // Verify filter button is enabled
    await expect(filterButton).toBeEnabled();

    // Click filter button
    await filterButton.click();

    // Verify table rows are filtered and result count is updated
    const filteredRowCount = page.locator('[data-testid="table-row"]').count();
    expect(filteredRowCount).toBeLessThanOrEqual(10);

    const resultCount = page.locator('[data-testid="table-result-count"]').textContent().trim();
    expect(resultCount).toBe('1 result');

    // Verify only matching row is visible
    const matchingRow = page.locator('[data-testid="table-row"]').first();
    await expect(matchingRow).toBeVisible();

    // Verify row has correct data
    const rowData = await matchingRow.textContent();
    expect(rowData).toContain('test');

    // Verify no other rows are visible
    const nonMatchingRows = page.locator('[data-testid="table-row"]').filter({
      has: page.locator('[data-testid="table-row"]').first()
    });
    await expect(nonMatchingRows).not.toBeVisible();

    // Verify search input is cleared after filter
    await expect(searchInput).toHaveValue('');

    // Verify result count is reset
    const resultCount = page.locator('[data-testid="table-result-count"]').textContent().trim();
    expect(resultCount).toBe('0 results');
  });

  test('should handle empty search input and display all rows', async ({ page }) => {
    // Verify initial table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify initial row count
    const rowCount = page.locator('[data-testid="table-row"]').count();
    expect(rowCount).toBeGreaterThan(0);

    // Verify search input is visible and has placeholder
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();
    await expect(searchInput).toContainText('Search');

    // Verify filter button is visible
    const filterButton = page.getByRole('button', { name: /filter/i });
    await expect(filterButton).toBeVisible();

    // Verify no results are displayed initially
    const resultCount = page.locator('[data-testid="table-result-count"]').textContent().trim();
    expect(resultCount).toBe('0 results');

    // Clear search input
    await searchInput.fill('');

    // Verify search input is empty
    await expect(searchInput).toHaveValue('');

    // Verify all rows are visible after clearing search
    const allRows = page.locator('[data-testid="table-row"]');
    await expect(allRows).toHaveCount(rowCount);

    // Verify result count is updated to show all rows
    const resultCount = page.locator('[data-testid="table-result-count"]').textContent().trim();
    expect(resultCount).toBe('10 results');

    // Verify no filter button is enabled
    const filterButton = page.getByRole('button', { name: /filter/i });
    await expect(filterButton).not.toBeEnabled();

    // Verify table rows are visible and have correct data
    const firstRow = page.locator('[data-testid="table-row"]').first();
    await expect(firstRow).toBeVisible();
    const firstRowData = await firstRow.textContent();
    expect(firstRowData).not.toContain('test');

    // Verify table has correct column headers
    const headers = page.locator('[data-testid="table-header"]');
    const headerCount = await headers.count();
    expect(headerCount).toBe(5);

    // Verify table has correct column names
    const headerText = await headers.first().textContent();
    expect(headerText).toBe('ID');
    expect(headerText).toBe('Name');
    expect(headerText).toBe('Email');
    expect(headerText).toBe('Phone');
    expect(headerText).toBe('Address');
  });
});
